    const f = (x, y) => [LO + x * SIZE, LO + y / bp.Hh * SIZE];
    let polys = [];
    bp.paths.forEach(p => { polys = polys.concat(strokeOutline(xform(p, f), STEM_S, CONTRAST)); });
    if (o.ringA && o.a) { const tr = topRight(bp.A, f); polys = polys.concat(ringPolys(tr[0] + 3.0, tr[1] + RING_R - 1.0)); }
    if (o.ringD && o.d) { const tr = topRight(bp.D, f); polys = polys.concat(ringPolys(tr[0] + 3.0, tr[1] + RING_R - 1.0)); }
