  // ------------------------------------------------------------------ text -> HTML
  const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const svgOf = (polys, label) => '<svg class="kamo" viewBox="0 0 100 100" role="img" aria-label="' + esc(label) + '"><path fill="currentColor" fill-rule="nonzero" d="' + polysD(polys) + '"/></svg>';
  const TOK = /^\\([a-z][a-z']*\d?)(?:\\([1-4]))?/;
